import {alerts,triage,makeReview,evaluate} from './engine.js';
const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let selected=alerts[0].id,filter='All',results=null,history=[];
try{const saved=JSON.parse(localStorage.getItem('soc-review-v1')||'[]');if(Array.isArray(saved))history=saved.filter(x=>x&&alerts.some(a=>a.id===x.id)&&['Approved','Needs investigation','Rejected'].includes(x.decision)&&typeof x.note==='string'&&typeof x.timestamp==='string').slice(-500);}catch{}
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4000);}
function latest(id){return history.filter(h=>h.id===id).at(-1);}
function renderList(){const q=$('#search').value.toLowerCase();const list=alerts.filter(a=>(filter==='All'||triage(a).verdict===filter)&&[a.title,a.id,a.host,a.source].join(' ').toLowerCase().includes(q));$('#alert-list').innerHTML=list.map(a=>`<button class="alert ${selected===a.id?'active':''}" data-id="${a.id}" aria-pressed="${selected===a.id}"><div class="alert-top"><span>${a.id} · ${a.time}</span><span class="badge ${triage(a).verdict}">${triage(a).verdict}</span></div><h3>${esc(a.title)}</h3><small>${esc(a.source)} · ${esc(a.host)}${latest(a.id)?' · Reviewed':''}</small></button>`).join('')||'<div class="empty">No alerts match. Try another search or filter.</div>';$('#review-count').textContent=String(new Set(history.map(h=>h.id)).size).padStart(2,'0');}
function detail(){const a=alerts.find(a=>a.id===selected),d=triage(a),r=latest(a.id);$('#detail').innerHTML=`<div class="detail-head"><div class="meta"><span>${a.id}</span><span class="badge ${d.verdict}">${d.verdict}</span><span>Needs human judgment</span></div><h2>${esc(a.title)}</h2><p>${esc(a.host)} · ${esc(a.user)} · ${esc(a.ip)}</p></div><div class="detail-body"><div class="section-label">TRIAGE DRAFT <span class="tag">RULE ${d.rule}</span></div><div class="draft"><p>${esc(d.reason)}</p><p>${esc(d.next)}</p><div>${d.citations.map(id=>`<a class="cite" href="#e-${id}" data-evidence="${id}">${id} ↗</a>`).join('')}</div><small style="margin-top:12px">${esc(d.limits)}</small></div><div class="section-label">SUPPORTING EVIDENCE <span>${a.evidence.length} RECORDS</span></div>${a.evidence.map(([id,title,text])=>`<details class="evidence" id="e-${id}"><summary><span>${id}</span>${esc(title)}</summary><p>${esc(text)}</p></details>`).join('')}<details class="evidence"><summary><span>RAW</span>Original alert narrative · untrusted</summary><p>${esc(a.description)}</p></details><div class="review"><div class="section-label">YOUR REVIEW <span>LOCAL ONLY</span></div><label for="review-note" class="note-label">Decision note <span aria-hidden="true">*</span></label><textarea id="review-note" maxlength="1500" required placeholder="What did you verify? What context is still missing?">${r?esc(r.note):''}</textarea><div class="actions"><button class="button" data-decision="Approved">Approve draft ✓</button><button class="button secondary" data-decision="Needs investigation">Investigate further</button><button class="button secondary" data-decision="Rejected">Reject draft</button></div>${r?`<div class="review-status">${esc(r.decision)} · ${esc(new Date(r.timestamp).toLocaleString())}</div>`:''}<p style="font-size:10px;margin-bottom:0">Records a local review only. Does not close an incident or trigger containment.</p></div></div>`;}
function renderHistory(){$('#history-list').innerHTML=[...history].reverse().map(h=>`<article class="history-card"><h3>${esc(h.id)} · ${esc(h.decision)}</h3><small>${esc(new Date(h.timestamp).toLocaleString())}</small><p>${esc(h.note)}</p></article>`).join('')||'<div class="empty">No decisions yet. Review an alert to start the trail.</div>';}
function view(name){if(!['queue','evaluation','history','about'].includes(name))name='queue';document.querySelectorAll('.view').forEach(s=>s.hidden=s.id!==name);document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===name));$('#crumb').textContent={queue:'Alert queue',evaluation:'Evaluation lab',history:'Review history',about:'System overview'}[name];if(name==='history')renderHistory();}
function download(name,data){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.querySelector('nav').addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(b){location.hash=b.dataset.view;view(b.dataset.view);}});
addEventListener('hashchange',()=>{if(!location.hash.startsWith('#e-'))view(location.hash.slice(1));});
$('#search').addEventListener('input',renderList);
document.querySelector('.filterbar').addEventListener('click',e=>{const b=e.target.closest('[data-filter]');if(!b)return;filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('selected',x===b));renderList();});
$('#alert-list').addEventListener('click',e=>{const b=e.target.closest('[data-id]');if(b){selected=b.dataset.id;renderList();detail();}});
$('#detail').addEventListener('click',e=>{const cite=e.target.closest('[data-evidence]');if(cite){e.preventDefault();const el=document.getElementById('e-'+cite.dataset.evidence);el.open=true;el.scrollIntoView({behavior:'smooth',block:'nearest'});}const b=e.target.closest('[data-decision]');if(!b)return;try{const record=makeReview(selected,b.dataset.decision,$('#review-note').value);const next=[...history,record].slice(-500);localStorage.setItem('soc-review-v1',JSON.stringify(next));history=next;renderList();detail();toast('Review recorded in this browser.');}catch(err){toast(err.message);$('#review-note').focus();}});
$('#reset').addEventListener('click',()=>{if(!confirm('Clear all local review decisions and reset this demo workspace?'))return;try{localStorage.removeItem('soc-review-v1');history=[];selected=alerts[0].id;filter='All';$('#search').value='';document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('selected',b.dataset.filter==='All'));renderList();detail();toast('Workspace reset.');}catch{toast('Browser storage is unavailable.');}});
$('#run-eval').addEventListener('click',()=>{results=evaluate();const table=rows=>`<table class="result-table"><thead><tr><th>Check</th><th>Expected</th><th>Observed</th><th>Result</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.name)}</td><td>${esc(r.expected)}</td><td>${esc(r.actual)}</td><td class="${r.pass?'pass':'fail'}">${r.pass?'PASS':'FAIL'}</td></tr>`).join('')}</tbody></table>`;const rows=[...results.triageRows,...results.boundaryRows];$('#eval-results').innerHTML=`<div class="callout"><strong>${rows.filter(r=>r.pass).length} / ${rows.length} development checks passed</strong><br>Executed ${esc(new Date(results.timestamp).toLocaleString())}. These fixtures are known to the implementation.</div><h2 class="result-heading">Triage fixture consistency</h2>${table(results.triageRows)}<h2 class="result-heading">Capability and narrative checks</h2>${table(results.boundaryRows)}`;$('#export-eval').disabled=false;});
$('#export-eval').addEventListener('click',()=>results&&download('soc-review-development-checks.json',results));$('#export-history').addEventListener('click',()=>download('soc-review-local-decisions.json',{scope:'Synthetic demo; editable local records',decisions:history}));
renderList();detail();view(location.hash.slice(1));
